// Import Vue, ref, onMounted, and onUnmounted from 'vue'
import { ref, onMounted, onUnmounted } from 'vue';

// Create and export a default Vue component named 'AuthSyncApp' with a setup function
export default {
  name: 'AuthSyncApp',
  setup() {
    // Initialize isAuthenticated state here
    const isAuthenticated = ref(false);

    // Define handleStorageChange function here
    const handleStorageChange = (event) => {
      if (event.key === 'auth' && event.newValue) {
        isAuthenticated.value = JSON.parse(event.newValue);
      }
    };

    // Add onMounted and onUnmounted hooks here to set up and clean up the storage event listener
    onMounted(() => {
      window.addEventListener('storage', handleStorageChange);
    });

    onUnmounted(() => {
      window.removeEventListener('storage', handleStorageChange);
    });

    // Create login handler function here
    const login = () => {
      isAuthenticated.value = true;
      localStorage.setItem('auth', JSON.stringify(true));
    };

    // Create logout handler function here
    const logout = () => {
      isAuthenticated.value = false;
      localStorage.setItem('auth', JSON.stringify(false));
    };

    return {
      isAuthenticated,
      login,
      logout
    };
  }
};

